    39  /* expects single line, checks if it's a codefence and extracts language */
    40  static int
    41  parse_codefence(hoedown_document *doc, uint8_t *data, size_t size, hoedown_buffer *lang, size_t *width, uint8_t *chr, unsigned int flags, hoedown_buffer *attr)
    42  {
    43          size_t i, w, lang_start, attr_start = 0;
    44
    45          i = w = is_codefence(data, size, width, chr);
    46          if (i == 0)
    47                  return 0;
    48
    49          while (i < size && _isspace(data[i]))
    50                  i++;
    51
    52          lang_start = i;
    53
    54          if (flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
    55                  attr_start = i + parse_attributes(data + i, size - i, attr, NULL, "", 0, 0, doc->attr_activation);
    56                  while (i < attr_start) {
    57                          if (_isspace(data[i])) {
    58                                  break;
    59                          }
    60                          i++;
    61                  }
    62          } else {
    63                  while (i < size && !_isspace(data[i]))
    64                          i++;
    65          }
    66
    67          lang->data = data + lang_start;
    68          lang->size = i - lang_start;
    69
    70          /* Avoid parsing a codespan as a fence */
    71          i = lang_start + 2;
    72          while (i < size && !(data[i] == *chr && data[i-1] == *chr && data[i-2] == *chr)) i++;
    73          if (i < size) return 0;
    74
    75          return w;
    76  }
