   148  static int
   149  is_next_headerline(uint8_t *data, size_t size)
   150  {
   151          size_t i = 0;
   152
   153          while (i < size && data[i] != '\n')
   154                  i++;
   155
   156          if (++i >= size)
   157                  return 0;
   158
   159          return is_headerline(data + i, size - i);
   160  }
