   162  /* prefix_quote • returns blockquote prefix length */
   163  static size_t
   164  prefix_quote(uint8_t *data, size_t size)
   165  {
   166          size_t i = 0;
   167          if (i < size && data[i] == ' ') i++;
   168          if (i < size && data[i] == ' ') i++;
   169          if (i < size && data[i] == ' ') i++;
   170
   171          if (i < size && data[i] == '>') {
   172                  if (i + 1 < size && data[i + 1] == ' ')
   173                          return i + 2;
   174
   175                  return i + 1;
   176          }
   177
   178          return 0;
   179  }
