   181  /* prefix_code • returns prefix length for block code*/
   182  static size_t
   183  prefix_code(uint8_t *data, size_t size)
   184  {
   185          if (size > 3 && data[0] == ' ' && data[1] == ' '
   186                  && data[2] == ' ' && data[3] == ' ') return 4;
   187
   188          return 0;
   189  }
