   191  /* prefix_oli • returns ordered list item prefix */
   192  static size_t
   193  prefix_oli(uint8_t *data, size_t size)
   194  {
   195          size_t i = 0;
   196
   197          if (i < size && data[i] == ' ') i++;
   198          if (i < size && data[i] == ' ') i++;
   199          if (i < size && data[i] == ' ') i++;
   200
   201          if (i >= size || data[i] < '0' || data[i] > '9')
   202                  return 0;
   203
   204          while (i < size && data[i] >= '0' && data[i] <= '9')
   205                  i++;
   206
   207          if (i + 1 >= size || data[i] != '.' || data[i + 1] != ' ')
   208                  return 0;
   209
   210          if (is_next_headerline(data + i, size - i))
   211                  return 0;
   212
   213          return i + 2;
   214  }
