   216  /* prefix_uli • returns unordered list item prefix */
   217  static size_t
   218  prefix_uli(uint8_t *data, size_t size)
   219  {
   220          size_t i = 0;
   221
   222          if (i < size && data[i] == ' ') i++;
   223          if (i < size && data[i] == ' ') i++;
   224          if (i < size && data[i] == ' ') i++;
   225
   226          if (i + 1 >= size ||
   227                  (data[i] != '*' && data[i] != '+' && data[i] != '-') ||
   228                  data[i + 1] != ' ')
   229                  return 0;
   230
   231          if (is_next_headerline(data + i, size - i))
   232                  return 0;
   233
   234          return i + 2;
   235  }
