   237  /* prefix_dt • returns dictionary definition prefix
   238   * this is in the form of /\s{0,3}:/ (e.g. "  :", where spacing is optional) */
   239  static size_t
   240  prefix_dt(uint8_t *data, size_t size)
   241  {
   242          size_t i = 0;
   243
   244          /* skip up to 3 whitespaces (since it's an indented codeblock at 4) */
   245          if (i < size && data[i] == ' ') i++;
   246          if (i < size && data[i] == ' ') i++;
   247          if (i < size && data[i] == ' ') i++;
   248
   249          /* if the first character after whitespaces isn't :, it isn't a dt */
   250          if (i + 1 >= size ||
   251                  data[i] != ':' ||
   252                  data[i + 1] != ' ')
   253                  return 0;
   254
   255          if (is_next_headerline(data + i, size - i))
   256                  return 0;
   257
   258          return i + 2;
   259  }
