   266  /* prefix_dli • returns dictionary definition prefix
   267   * a dli looks like a block of text, followed by optional whitespace, followed
   268   * by another block with : as the first non-whitespace character */
   269  static size_t
   270  prefix_dli(hoedown_document *doc, uint8_t *data, size_t size)
   271  {
   272          /* end is to keep track of the final return value */
   273          size_t i = 0, j = 0, end = 0;
   274          int empty = 0;
   275
   276          /* if the first line has a : in front of it, it can't be a definition list
   277           * that starts at this point */
   278          if (prefix_dt(data, size)) {
   279                  return 0;
   280          }
   281
   282          /* temporarily toggle definition lists off to prevent infinite loops */
   283          doc->ext_flags &= ~HOEDOWN_EXT_DEFINITION_LISTS;
   284
   285          /* check if it is a block of text with no double newlines inside, followed by
   286           *  another block of text starting with : */
   287          while (i < size) {
   288                  /* if the line we are on is empty, flip the empty flag to indicate that
   289                   * the next block of text we see has to start with : to be considered
   290                   * a definition list; then skip to the next line */
   291                  j = is_empty(data + i, size - i);
   292                  if(j != 0) {
   293                          empty = 1;
   294                          i += j;
   295                          continue;
   296                  }
   297
   298                  /* if anything special is found while parsing the definition term part,
   299                   * then return so that the main loop can deal with it */
   300                  if (!is_paragraph(doc, data + i, size - i)) {
   301                          break;
   302                  }
   303
   304                  /* check if the current line starts with :, returning the position of the
   305                   * beginning of the line if it does */
   306                  j = prefix_dt(data + i, size - i);
   307                  if (j > 0) {
   308                          end = i;
   309                          break;
   310                  } else if(empty) {
   311                          /* if an empty newline has been found, then since : was not the first
   312                           * character after whitespaces, it can't be a definition list */
   313                          break;
   314                  }
   315                  /* scan characters until the next newline */
   316                  for (i = i + 1; i < size && data[i - 1] != '\n'; i++);
   317          }
   318
   319          doc->ext_flags |= HOEDOWN_EXT_DEFINITION_LISTS;
   320          return end;
   321  }
