   328  /* parse_blockquote • handles parsing of a blockquote fragment */
   329  static size_t
   330  parse_blockquote(hoedown_buffer *ob, hoedown_document *doc, uint8_t *data, size_t size)
   331  {
   332          size_t beg, end = 0, pre, work_size = 0;
   333          uint8_t *work_data = 0;
   334          hoedown_buffer *out = 0;
   335
   336          doc->blockquote_depth++;
   337
   338          out = newbuf(doc, BUFFER_BLOCK);
   339          beg = 0;
   340          while (beg < size) {
   341                  for (end = beg + 1; end < size && data[end - 1] != '\n'; end++);
   342
   343                  pre = prefix_quote(data + beg, end - beg);
   344
   345                  if (pre)
   346                          beg += pre; /* skipping prefix */
   347
   348                  /* empty line finished */
   349                  else if ((doc->ext_flags & HOEDOWN_EXT_BLOCKQUOTE_EMPTY_LINE) &&
   350                                  (is_empty(data + beg, end - beg)))
   351                          break;
   352
   353                  /* empty line followed by non-quote line */
   354                  else if (is_empty(data + beg, end - beg) &&
   355                                  (end >= size || (prefix_quote(data + end, size - end) == 0 &&
   356                                  !is_empty(data + end, size - end))))
   357                          break;
   358
   359                  if (beg < end) { /* copy into the in-place working buffer */
   360                          /* hoedown_buffer_put(work, data + beg, end - beg); */
   361                          if (!work_data)
   362                                  work_data = data + beg;
   363                          else if (data + beg != work_data + work_size)
   364                                  memmove(work_data + work_size, data + beg, end - beg);
   365                          work_size += end - beg;
   366                  }
   367                  beg = end;
   368          }
   369
   370          parse_block(out, doc, work_data, work_size);
   371          if (doc->md.blockquote)
   372                  doc->md.blockquote(ob, out, &doc->data);
   373          popbuf(doc, BUFFER_BLOCK);
   374
   375          doc->blockquote_depth--;
   376
   377          return end;
   378  }
