   383  /* parse_paragraph • handles parsing of a regular paragraph */
   384  static size_t
   385  parse_paragraph(hoedown_buffer *ob, hoedown_document *doc, uint8_t *data, size_t size)
   386  {
   387          hoedown_buffer work = { NULL, 0, 0, 0, NULL, NULL, NULL };
   388          size_t i = 0, end = 0;
   389          int level = 0;
   390
   391          work.data = data;
   392
   393          while (i < size) {
   394                  for (end = i + 1; end < size && data[end - 1] != '\n'; end++) /* empty */;
   395
   396                  if (is_empty(data + i, size - i))
   397                          break;
   398
   399                  if ((level = is_headerline(data + i, size - i)) != 0) {
   400                          if (i == 0) {
   401                                  level = 0;
   402                                  i = end;
   403                          }
   404                          break;
   405                  }
   406
   407                  if (is_atxheader(doc, data + i, size - i) ||
   408                          is_hrule(data + i, size - i) ||
   409                          prefix_quote(data + i, size - i)) {
   410                          end = i;
   411                          break;
   412                  }
   413
   414                  i = end;
   415          }
   416
   417          work.size = i;
   418          while (work.size && data[work.size - 1] == '\n')
   419                  work.size--;
   420
   421          if (!level) {
   422                  hoedown_buffer *attr = newbuf(doc, BUFFER_ATTRIBUTE);
   423                  if (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
   424                          parse_attributes(work.data, work.size, NULL, attr, "paragraph", 9, 1, doc->attr_activation);
   425                          if (attr->size > 0) {
   426                                  /* remove the length of the attribute from the work size - the 12 comes
   427                                  * from the leading space (1), the paragraph (9), the @ symbol (1), and
   428                                  * the {} (2) (any extra spaces in the attribute are included inside
   429                                  * the attribute) */
   430                                  work.size -= attr->size + 12;
   431                          }
   432                  }
   433
   434                  hoedown_buffer *tmp = newbuf(doc, BUFFER_BLOCK);
   435                  parse_inline(tmp, doc, work.data, work.size);
   436                  if (doc->md.paragraph)
   437                          doc->md.paragraph(ob, tmp, attr, &doc->data);
   438                  popbuf(doc, BUFFER_BLOCK);
   439                  popbuf(doc, BUFFER_ATTRIBUTE);
   440          } else {
   441                  hoedown_buffer *header_work;
   442                  hoedown_buffer *attr_work;
   443                  size_t len;
   444
   445                  if (work.size) {
   446                          size_t beg;
   447                          i = work.size;
   448                          work.size -= 1;
   449
   450                          while (work.size && data[work.size] != '\n')
   451                                  work.size -= 1;
   452
   453                          beg = work.size + 1;
   454                          while (work.size && data[work.size - 1] == '\n')
   455                                  work.size -= 1;
   456
   457                          if (work.size > 0) {
   458                                  hoedown_buffer *tmp = newbuf(doc, BUFFER_BLOCK);
   459                                  parse_inline(tmp, doc, work.data, work.size);
   460
   461                                  if (doc->md.paragraph)
   462                                          doc->md.paragraph(ob, tmp, NULL, &doc->data);
   463
   464                                  popbuf(doc, BUFFER_BLOCK);
   465                                  work.data += beg;
   466                                  work.size = i - beg;
   467                          }
   468                          else work.size = i;
   469                  }
   470
   471                  header_work = newbuf(doc, BUFFER_SPAN);
   472                  attr_work = newbuf(doc, BUFFER_ATTRIBUTE);
   473
   474                  len = work.size;
   475                  if (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
   476                          len = parse_attributes(work.data, work.size, attr_work, NULL, "", 0, 1, doc->attr_activation);
   477                  }
   478
   479                  parse_inline(header_work, doc, work.data, len);
   480
   481                  if (doc->md.header) {
   482                          doc->header_type = HOEDOWN_HEADER_SETEXT;
   483                          doc->md.header(ob, header_work, attr_work, (int)level, &doc->data);
   484                          doc->header_type = HOEDOWN_HEADER_NONE;
   485                  }
   486
   487                  popbuf(doc, BUFFER_SPAN);
   488                  popbuf(doc, BUFFER_ATTRIBUTE);
   489          }
   490
   491          return end;
   492  }
